const raw = $input.first().json;
const posts = Array.isArray(raw) ? raw : (raw.posts || []);
const weekAgo = new Date(Date.now() - 7 * 86400000);
const recent = posts.filter(p => new Date(p.publishDate || p.createdAt) >= weekAgo);
let totalLikes = 0, totalComments = 0, totalImpressions = 0;
for (const p of recent) {
  if (p.analytics) {
    totalLikes += p.analytics.likes || 0;
    totalComments += p.analytics.comments || 0;
    totalImpressions += p.analytics.impressions || 0;
  }
}
const top = recent
  .filter(p => p.analytics)
  .sort((a, b) => ((b.analytics.likes||0)*3+(b.analytics.impressions||0)*0.01) - ((a.analytics.likes||0)*3+(a.analytics.impressions||0)*0.01))
  .slice(0, 3)
  .map(p => ({ content: (p.posts?.[0]?.value?.[0]?.content || '').substring(0, 80), likes: p.analytics.likes || 0, impressions: p.analytics.impressions || 0 }));
const topText = top.map((t,i) => `${i+1}. ${t.content}... (${t.likes} likes, ${t.impressions} imp)`).join('\n');
return [{ json: {
  postCount: recent.length,
  totalLikes, totalComments, totalImpressions,
  topText: topText || 'No analytics data yet',
  hasData: recent.length > 0
} }];
